404.html:
{% extends 'base.html' %}

{% block title %}Page Not Found | RUDRAM 2.0{% endblock %}
{% block meta_description %}The requested RUDRAM page could not be found. Return to the disaster intelligence dashboard.{% endblock %}
{% block page_heading %}{% endblock %}

{% block content %}
<section class="rudram-card text-center py-5 my-4" aria-labelledby="notFoundTitle">
    <p class="display-1 fw-bold text-primary mb-0">404</p>
    <h1 id="notFoundTitle" class="h3 fw-bold mt-2">We couldn't find that page</h1>
    <p class="text-secondary mx-auto mb-4" style="max-width: 34rem;">
        The address may be outdated or the page may have moved. Use the dashboard to continue.
    </p>
    <a href="{% url 'dashboard' %}" class="btn btn-primary px-4">Return to dashboard</a>
</section>
{% endblock %}

satellite/index.html:
{% extends 'base.html' %}

{% block title %}RUDRAM - Satellite Analysis Lab & SAR Damage Analytics{% endblock %}
{% block meta_description %}Analyze satellite imagery and flood conditions with RUDRAM Sentinel-1 SAR and Sentinel-2 monitoring tools.{% endblock %}
{% block page_heading %}RUDRAM Satellite Analysis Lab (Sentinel-1 / Sentinel-2 / U-Net){% endblock %}

{% block content %}
<div class="alert alert-warning">Live satellite analysis is currently unavailable. No satellite results are being generated in this deployment.</div>
<!-- Control & Sensor Parameter Ribbon -->
<div class="rudram-card mb-4">
    <div class="row g-3 align-items-center">
        <div class="col-lg-3">
            <label class="form-label small text-secondary">Area of Interest (AOI)</label>
            <input type="text" id="aoiInput" class="form-control form-control-sm bg-dark border-secondary text-light" value="Bhubaneswar Floodplain Sector">
        </div>
        <div class="col-lg-2">
            <label class="form-label small text-secondary">Pre-Disaster Baseline Date</label>
            <input type="date" id="preDate" class="form-control form-control-sm bg-dark border-secondary text-light" value="2026-08-01">
        </div>
        <div class="col-lg-2">
            <label class="form-label small text-secondary">Post-Disaster SAR Date</label>
            <input type="date" id="postDate" class="form-control form-control-sm bg-dark border-secondary text-light" value="2026-08-14">
        </div>
        <div class="col-lg-3">
            <label class="form-label small text-secondary">Processing Pipeline</label>
            <select id="sensorSelect" class="form-select form-select-sm bg-dark border-secondary text-light">
                <option value="SENTINEL_1" selected>Sentinel-1 SAR C-Band (All-Weather Radar)</option>
                <option value="SENTINEL_2">Sentinel-2 MSI Optical (NDWI / NDVI)</option>
                <option value="UNET_CNN">Deep Learning PyTorch U-Net Segmentation</option>
            </select>
        </div>
        <div class="col-lg-2 d-flex align-items-end">
            <button class="btn btn-primary btn-sm w-100 fw-bold d-flex align-items-center justify-content-center gap-1" id="btnRunSatelliteAnalysis" onclick="executeSatelliteWorkflow()">
                <i data-lucide="satellite" style="width: 16px; height: 16px;"></i>
                ANALYZE DAMAGE
            </button>
        </div>
    </div>
</div>

<!-- Interactive Progress Bar (Non-Freezing Background Workflow) -->
<div id="satProgressContainer" class="rudram-card mb-4 d-none">
    <div class="d-flex align-items-center justify-content-between mb-2 small">
        <strong class="text-info" id="satProgressTitle">1. Searching Copernicus Sentinel-1 GRD Catalog...</strong>
        <span class="text-secondary" id="satProgressPercent">20%</span>
    </div>
    <div class="progress bg-dark mb-3" style="height: 8px;">
        <div class="progress-bar progress-bar-striped progress-bar-animated bg-info" id="satProgressBar" style="width: 20%;"></div>
    </div>
    <div class="row g-2 text-center small text-secondary" id="satStepsRow">
        <div class="col"><span class="badge bg-primary w-100">1. Query Imagery</span></div>
        <div class="col"><span class="badge bg-secondary w-100">2. Lee Speckle Filter</span></div>
        <div class="col"><span class="badge bg-secondary w-100">3. SAR dB Difference</span></div>
        <div class="col"><span class="badge bg-secondary w-100">4. Slope Masking</span></div>
        <div class="col"><span class="badge bg-secondary w-100">5. Polygon GeoJSON</span></div>
    </div>
</div>

<!-- Before & After Comparison Split Slider -->
<div class="row g-4 mb-4">
    <div class="col-lg-7">
        <div class="rudram-card p-0 overflow-hidden">
            <div class="p-3 border-bottom border-secondary border-opacity-25 d-flex align-items-center justify-content-between">
                <div class="d-flex align-items-center gap-2">
                    <i data-lucide="split" class="text-info" style="width: 18px; height: 18px;"></i>
                    <span class="fw-bold">Before / After Disaster Inundation Comparison</span>
                </div>
                <span class="badge badge-demo">Simulated Multi-Spectral Visualizer</span>
            </div>

            <div class="comparison-container" id="sliderContainer">
                <!-- Background Image (Post-Disaster Inundated Image) -->
                <div class="comparison-image" style="background: radial-gradient(circle at 60% 50%, #0369a1 0%, #0f172a 75%); display: flex; align-items: center; justify-content: center;">
                    <div class="text-center p-4">
                        <div class="badge bg-danger mb-2 fs-6">POST-EVENT (SENTINEL-1 SAR FLOOD WATER MASK)</div>
                        <div class="text-white fs-4 fw-bold">28.4 km² Surface Inundation Detected</div>
                        <div class="text-info small">Dark radar specular backscatter regions vectorized in blue overlay</div>
                    </div>
                </div>

                <!-- Foreground Clipping Box (Pre-Disaster Baseline) -->
                <div class="comparison-slider-wrapper" id="sliderWrapper" style="width: 50%;">
                    <div class="comparison-image" style="width: 200%; background: radial-gradient(circle at 30% 50%, #15803d 0%, #0f172a 75%); display: flex; align-items: center; justify-content: flex-start; padding-left: 50px;">
                        <div class="text-start">
                            <div class="badge bg-success mb-2 fs-6">PRE-EVENT (NORMAL DRY SURFACE BASELINE)</div>
                            <div class="text-white fs-4 fw-bold">Nominal Riverbank Confinement</div>
                            <div class="text-light small">Aug 01, 2026 Baseline Surface Reflectance</div>
                        </div>
                    </div>
                </div>

                <!-- Interactive Swipe Divider Handle -->
                <div class="comparison-handle" id="sliderHandle" style="left: 50%;">
                    <div class="comparison-circle">
                        <i data-lucide="chevrons-left-right" class="text-dark" style="width: 18px; height: 18px;"></i>
                    </div>
                </div>
            </div>
            <div class="p-2 text-center small text-secondary">
                &larr; Drag slider left/right to compare pre-flood dry conditions against active radar inundation &rarr;
            </div>
        </div>
    </div>

    <!-- Damage Analytics Metrics -->
    <div class="col-lg-5">
        <div class="rudram-card h-100">
            <h6 class="fw-bold mb-3 small text-uppercase text-secondary">Copernicus SAR Geospatial Metrics</h6>

            <div class="row g-3 mb-4 text-center">
                <div class="col-6">
                    <div class="p-3 bg-dark bg-opacity-50 rounded border border-secondary border-opacity-25">
                        <div class="small text-secondary">Total Inundated Area</div>
                        <div class="fs-3 fw-bold text-danger">28.4 <small class="fs-6">km²</small></div>
                        <div class="badge-source mt-1">Sentinel-1 C-Band</div>
                    </div>
                </div>
                <div class="col-6">
                    <div class="p-3 bg-dark bg-opacity-50 rounded border border-secondary border-opacity-25">
                        <div class="small text-secondary">Submerged Roadways</div>
                        <div class="fs-3 fw-bold text-warning">24.6 <small class="fs-6">km</small></div>
                        <div class="badge-source mt-1">OSM Road Network</div>
                    </div>
                </div>
                <div class="col-6">
                    <div class="p-3 bg-dark bg-opacity-50 rounded border border-secondary border-opacity-25">
                        <div class="small text-secondary">Inundated Farmland</div>
                        <div class="fs-3 fw-bold text-info">19.2 <small class="fs-6">km²</small></div>
                        <div class="badge-source mt-1">Sentinel-2 NDVI</div>
                    </div>
                </div>
                <div class="col-6">
                    <div class="p-3 bg-dark bg-opacity-50 rounded border border-secondary border-opacity-25">
                        <div class="small text-secondary">SAR Confidence Index</div>
                        <div class="fs-3 fw-bold text-success">93.0%</div>
                        <div class="badge-source mt-1">Speckle Filtered</div>
                    </div>
                </div>
            </div>

            <!-- Optical Indices Breakdown -->
            <h6 class="fw-bold small text-secondary mb-2">Spectral Change Detection Indices (Sentinel-2)</h6>
            <div class="d-flex flex-column gap-2 small">
                <div class="d-flex justify-content-between p-2 bg-dark bg-opacity-50 rounded">
                    <span><strong>NDWI Water Expansion:</strong></span>
                    <span class="text-danger fw-bold">+3.6x Normal Surface Water</span>
                </div>
                <div class="d-flex justify-content-between p-2 bg-dark bg-opacity-50 rounded">
                    <span><strong>NDVI Agricultural Inundation:</strong></span>
                    <span class="text-warning fw-bold">-18.5 sq.km Biomass Loss</span>
                </div>
                <div class="d-flex justify-content-between p-2 bg-dark bg-opacity-50 rounded">
                    <span><strong>PyTorch U-Net Segmentation F1:</strong></span>
                    <span class="text-info fw-bold">0.912 F1 Accuracy Score</span>
                </div>
            </div>
        </div>
    </div>
</div>
{% endblock %}

{% block extra_js %}
<script>
// Before / After Drag Slider Implementation
document.addEventListener('DOMContentLoaded', () => {
    const container = document.getElementById('sliderContainer');
    const wrapper = document.getElementById('sliderWrapper');
    const handle = document.getElementById('sliderHandle');
    let isDragging = false;

    function moveSlider(x) {
        const rect = container.getBoundingClientRect();
        let pos = (x - rect.left) / rect.width;
        pos = Math.max(0, Math.min(1, pos));
        wrapper.style.width = (pos * 100) + '%';
        handle.style.left = (pos * 100) + '%';
    }

    container.addEventListener('mousedown', () => isDragging = true);
    window.addEventListener('mouseup', () => isDragging = false);
    container.addEventListener('mousemove', (e) => {
        if (isDragging) moveSlider(e.clientX);
    });

    // Touch support for mobile
    container.addEventListener('touchmove', (e) => {
        if (e.touches.length > 0) moveSlider(e.touches[0].clientX);
    });
});

async function executeSatelliteWorkflow() {
    const pContainer = document.getElementById('satProgressContainer');
    const pBar = document.getElementById('satProgressBar');
    const pTitle = document.getElementById('satProgressTitle');
    const pPercent = document.getElementById('satProgressPercent');
    pContainer.classList.remove('d-none');

    const steps = [
        { title: '1. Querying Sentinel-1 GRD SAR Imagery...', p: 20 },
        { title: '2. Applying Refined Lee Speckle Filter...', p: 40 },
        { title: '3. Calculating Dual-Pol (VV/VH) Backscatter dB Difference...', p: 65 },
        { title: '4. Applying SRTM Elevation Slope Thresholding...', p: 85 },
        { title: '5. Vectorizing Flood Polygons & GeoJSON Layers...', p: 100 }
    ];

    for (let s of steps) {
        pTitle.innerText = s.title;
        pBar.style.width = s.p + '%';
        pPercent.innerText = s.p + '%';
        await new Promise(r => setTimeout(r, 600));
    }

    try {
        const res = await fetch('/api/satellite/flood-detection/', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                aoi: { lat: 20.2961, lon: 85.8245 },
                pre_event_date: document.getElementById('preDate').value,
                post_event_date: document.getElementById('postDate').value,
                aoi_name: document.getElementById('aoiInput').value
            })
        });
        const data = await res.json();
        if (data.success) {
            showToast('Satellite SAR Flood Extent Analysis Completed and Georeferenced!', 'success');
        } else {
            const msg = data.error || 'Live GEE data temporarily unavailable.';
            showToast(msg, 'warning');
            pTitle.innerText = msg;
            pTitle.className = 'text-warning';
        }
    } catch (e) {
        showToast('Live GEE data temporarily unavailable.', 'error');
    }
}
</script>
{% endblock %}

shelters/index.html:
{% extends 'base.html' %}

{% block title %}RUDRAM - Shelter Management & Recommendation{% endblock %}
{% block meta_description %}Find emergency shelters, check capacity and services, and get location-based recommendations from RUDRAM.{% endblock %}
{% block page_heading %}Emergency Shelters & Relief Camp Logistics{% endblock %}

{% block content %}
<!-- Quick Stats Banner -->
<div class="row g-3 mb-4">
    <div class="col-6 col-lg-3">
        <div class="rudram-card stat-widget">
            <div>
                <div class="stat-label">Total Camp Capacity</div>
                <div class="stat-value text-white">{{ total_cap|default:"0" }}</div>
            </div>
            <i data-lucide="home" class="text-secondary opacity-50" style="width: 32px; height: 32px;"></i>
        </div>
    </div>
    <div class="col-6 col-lg-3">
        <div class="rudram-card stat-widget">
            <div>
                <div class="stat-label">Current Occupancy</div>
                <div class="stat-value text-warning">{{ total_occ|default:"0" }}</div>
            </div>
            <i data-lucide="users" class="text-warning opacity-50" style="width: 32px; height: 32px;"></i>
        </div>
    </div>
    <div class="col-6 col-lg-3">
        <div class="rudram-card stat-widget">
            <div>
                <div class="stat-label">Available Capacity</div>
                <div class="stat-value text-success">{{ available_cap|default:"0" }}</div>
            </div>
            <i data-lucide="user-check" class="text-success opacity-50" style="width: 32px; height: 32px;"></i>
        </div>
    </div>
    <div class="col-6 col-lg-3">
        <div class="rudram-card stat-widget">
            <div>
                <div class="stat-label">Active Open Shelters</div>
                <div class="stat-value text-info">{{ open_count|default:"0" }}</div>
            </div>
            <i data-lucide="door-open" class="text-info opacity-50" style="width: 32px; height: 32px;"></i>
        </div>
    </div>
</div>

<!-- Recommendation & Finder Bar -->
<div class="rudram-card mb-4 bg-primary bg-opacity-10 border-primary border-opacity-25">
    <div class="d-flex flex-wrap align-items-center justify-content-between gap-3">
        <div>
            <h5 class="fw-bold mb-1 text-white"><i data-lucide="sparkles" class="me-2 text-info" style="width: 20px; height: 20px;"></i>Shelter Finder & Proximity Radar</h5>
            <div class="small text-secondary" id="shelterFinderStatusText">Filter real admin-created shelters within 10 km of your current GPS location.</div>
        </div>
        <div class="d-flex flex-wrap align-items-center gap-2">
            <button class="btn btn-info fw-bold d-flex align-items-center gap-2 px-3" id="btnNearbyShelters" onclick="findNearbyShelters(this)">
                <i data-lucide="navigation" style="width: 18px; height: 18px;"></i>
                NEARBY SHELTERS (10 KM)
            </button>
            <button class="btn btn-outline-light btn-sm fw-semibold d-none" id="btnAllShelters" onclick="resetSheltersList()">
                <i data-lucide="rotate-ccw" class="me-1" style="width: 14px; height: 14px;"></i>
                All Shelters
            </button>
            <button class="btn btn-primary fw-bold d-flex align-items-center gap-2 px-3" onclick="findBestShelter()">
                <i data-lucide="sparkles" style="width: 18px; height: 18px;"></i>
                FIND BEST SHELTER
            </button>
        </div>
    </div>
</div>

<!-- Shelters Cards Grid -->
<div class="row g-4" id="sheltersGrid">
    {% for shelter in shelters %}
    <div class="col-md-6 col-lg-4 shelter-card-item">
        <div class="rudram-card h-100 d-flex flex-column justify-content-between">
            <div>
                <div class="d-flex align-items-start justify-content-between mb-2">
                    <h6 class="fw-bold text-white mb-0">{{ shelter.name }}</h6>
                    <span class="badge bg-{% if shelter.status == 'OPEN' %}success{% elif shelter.status == 'NEAR_CAPACITY' %}warning text-dark{% else %}danger{% endif %}">
                        {{ shelter.status }}
                    </span>
                </div>
                <div class="small text-secondary mb-3">{{ shelter.address }}</div>

                <!-- Progress Bar -->
                <div class="mb-3">
                    <div class="d-flex justify-content-between small text-secondary mb-1">
                        <span>Occupancy ({{ shelter.current_occupancy }}/{{ shelter.total_capacity }})</span>
                        <strong class="text-{% if shelter.occupancy_percentage > 80 %}danger{% else %}info{% endif %}">{{ shelter.occupancy_percentage }}%</strong>
                    </div>
                    <div class="progress bg-dark" style="height: 6px;">
                        <div class="progress-bar bg-{% if shelter.occupancy_percentage > 80 %}danger{% else %}info{% endif %}" style="width: {{ shelter.occupancy_percentage }}%;"></div>
                    </div>
                </div>

                <!-- Feature Icons -->
                <div class="d-flex flex-wrap gap-2 small mb-3">
                    {% if shelter.has_potable_water %}<span class="badge bg-dark border border-secondary text-info"><i data-lucide="droplet" class="me-1" style="width: 12px; height: 12px;"></i>Water</span>{% endif %}
                    {% if shelter.has_food_stocks %}<span class="badge bg-dark border border-secondary text-success"><i data-lucide="utensils" class="me-1" style="width: 12px; height: 12px;"></i>Food</span>{% endif %}
                    {% if shelter.has_medical_station %}<span class="badge bg-dark border border-secondary text-danger"><i data-lucide="cross" class="me-1" style="width: 12px; height: 12px;"></i>Medical ICU</span>{% endif %}
                    {% if shelter.has_backup_generator %}<span class="badge bg-dark border border-secondary text-warning"><i data-lucide="zap" class="me-1" style="width: 12px; height: 12px;"></i>Generator</span>{% endif %}
                </div>

                <div class="small text-secondary mb-2">
                    <div><strong>Elevation:</strong> <span class="text-white">{{ shelter.elevation_m }}m a.s.l.</span></div>
                    <div><strong>Contact:</strong> <span class="text-white">{{ shelter.contact_person }} ({{ shelter.phone_number }})</span></div>
                </div>
            </div>

            <div class="pt-3 border-top border-secondary border-opacity-25 d-flex gap-2">
                <a href="{% url 'evacuation' %}?shelter_id={{ shelter.id }}" class="btn btn-sm btn-outline-info flex-fill">Route Here</a>
                <button class="btn btn-sm btn-outline-secondary" onclick="quickUpdateOccupancy({{ shelter.id }}, {{ shelter.current_occupancy }})">Update Headcount</button>
            </div>
        </div>
    </div>
    {% endfor %}
</div>

<!-- Modal for Best Shelter Recommendation Result -->
<div class="modal fade" id="bestShelterModal" tabindex="-1">
    <div class="modal-dialog modal-dialog-centered">
        <div class="modal-content bg-dark text-light border-info">
            <div class="modal-header border-secondary">
                <h5 class="modal-title d-flex align-items-center gap-2">
                    <i data-lucide="check-circle" class="text-success" style="width: 20px; height: 20px;"></i>
                    Top Recommended Safe Shelter
                </h5>
                <button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal"></button>
            </div>
            <div class="modal-body" id="bestShelterModalBody">
                <div class="text-center py-3">
                    <div class="spinner-border text-info mb-2" role="status"></div>
                    <div class="small text-secondary">Computing multi-criteria spatial suitability score...</div>
                </div>
            </div>
            <div class="modal-footer border-secondary">
                <a href="{% url 'evacuation' %}" class="btn btn-primary fw-bold w-100">Navigate Safe Route Now</a>
            </div>
        </div>
    </div>
</div>
{% endblock %}

{% block extra_js %}
<script>
function findNearbyShelters(btn) {
    if (!navigator.geolocation) {
        alert('Geolocation is not supported by your browser.');
        return;
    }

    const statusText = document.getElementById('shelterFinderStatusText');
    const originalBtnHtml = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Acquiring GPS...';
    if (statusText) statusText.innerText = 'Acquiring real current GPS location...';

    navigator.geolocation.getCurrentPosition(
        async (position) => {
            const lat = position.coords.latitude;
            const lon = position.coords.longitude;

            // Save to session storage for seamless map integration
            sessionStorage.setItem('rudram_lat', lat);
            sessionStorage.setItem('rudram_lon', lon);

            if (statusText) statusText.innerText = `GPS Acquired (Lat: ${lat.toFixed(4)}, Lon: ${lon.toFixed(4)}). Filtering shelters within 10 km...`;
            btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Filtering 10 km...';

            try {
                const res = await fetch(`/api/shelters/nearby/?latitude=${lat}&longitude=${lon}&radius=10`);
                const data = await res.json();

                const grid = document.getElementById('sheltersGrid');
                const btnAll = document.getElementById('btnAllShelters');
                if (btnAll) btnAll.classList.remove('d-none');

                if (res.ok && data.success && Array.isArray(data.shelters) && data.shelters.length > 0) {
                    let html = '';
                    data.shelters.forEach(s => {
                        const totalCap = s.total_capacity || 1000;
                        const currOcc = s.current_occupancy || 0;
                        const occPct = totalCap > 0 ? Math.round((currOcc / totalCap) * 100) : 0;
                        const statusClass = s.status === 'OPEN' ? 'success' : (s.status === 'NEAR_CAPACITY' ? 'warning text-dark' : 'danger');
                        const occClass = occPct > 80 ? 'danger' : 'info';

                        html += `
                            <div class="col-md-6 col-lg-4 shelter-card-item">
                                <div class="rudram-card h-100 d-flex flex-column justify-content-between border-info border-opacity-50">
                                    <div>
                                        <div class="d-flex align-items-start justify-content-between mb-2">
                                            <div>
                                                <h6 class="fw-bold text-white mb-0">${escapeHtml(s.name)}</h6>
                                                <span class="badge bg-info text-dark font-monospace mt-1"><i data-lucide="navigation" style="width: 11px; height: 11px;" class="me-1"></i>${s.distance_km} km away</span>
                                            </div>
                                            <span class="badge bg-${statusClass}">${s.status}</span>
                                        </div>
                                        <div class="small text-secondary mb-3">${escapeHtml(s.address)}</div>

                                        <div class="mb-3">
                                            <div class="d-flex justify-content-between small text-secondary mb-1">
                                                <span>Occupancy (${currOcc}/${totalCap})</span>
                                                <strong class="text-${occClass}">${occPct}%</strong>
                                            </div>
                                            <div class="progress bg-dark" style="height: 6px;">
                                                <div class="progress-bar bg-${occClass}" style="width: ${occPct}%;"></div>
                                            </div>
                                        </div>

                                        <div class="d-flex flex-wrap gap-2 small mb-3">
                                            ${s.has_potable_water ? '<span class="badge bg-dark border border-secondary text-info"><i data-lucide="droplet" class="me-1" style="width: 12px; height: 12px;"></i>Water</span>' : ''}
                                            ${s.has_food_stocks ? '<span class="badge bg-dark border border-secondary text-success"><i data-lucide="utensils" class="me-1" style="width: 12px; height: 12px;"></i>Food</span>' : ''}
                                            ${s.has_medical_station ? '<span class="badge bg-dark border border-secondary text-danger"><i data-lucide="cross" class="me-1" style="width: 12px; height: 12px;"></i>Medical ICU</span>' : ''}
                                            ${s.has_backup_generator ? '<span class="badge bg-dark border border-secondary text-warning"><i data-lucide="zap" class="me-1" style="width: 12px; height: 12px;"></i>Generator</span>' : ''}
                                        </div>

                                        <div class="small text-secondary mb-2">
                                            <div><strong>Elevation:</strong> <span class="text-white">${s.elevation_m}m a.s.l.</span></div>
                                            <div><strong>Contact:</strong> <span class="text-white">${escapeHtml(s.contact_person)} (${escapeHtml(s.phone_number)})</span></div>
                                        </div>
                                    </div>

                                    <div class="pt-3 border-top border-secondary border-opacity-25 d-flex gap-2">
                                        <a href="/evacuation/?shelter_id=${s.id}" class="btn btn-sm btn-outline-info flex-fill">Route Here</a>
                                        <button class="btn btn-sm btn-outline-secondary" onclick="quickUpdateOccupancy(${s.id}, ${currOcc})">Update Headcount</button>
                                    </div>
                                </div>
                            </div>
                        `;
                    });
                    grid.innerHTML = html;
                    if (statusText) statusText.innerText = `Showing ${data.count} registered shelter(s) within 10 km of your current GPS location.`;
                    if (window.lucide) lucide.createIcons();
                } else {
                    grid.innerHTML = `
                        <div class="col-12 text-center py-5">
                            <div class="rudram-card py-5 border-warning border-opacity-50">
                                <i data-lucide="map-pin-off" class="text-warning mb-3" style="width: 48px; height: 48px;"></i>
                                <h5 class="fw-bold text-white mb-2">No registered shelters found within 10 km.</h5>
                                <div class="small text-secondary mb-3">All registered emergency shelters in the database are located beyond your 10 km radius.</div>
                                <button class="btn btn-outline-info btn-sm" onclick="resetSheltersList()">View All Emergency Shelters</button>
                            </div>
                        </div>
                    `;
                    if (statusText) statusText.innerText = 'No registered shelters found within 10 km.';
                    if (window.lucide) lucide.createIcons();
                }
            } catch (err) {
                console.error('Nearby shelter fetch error:', err);
                alert('Nearby shelter service is temporarily unavailable.');
                if (statusText) statusText.innerText = 'Error fetching nearby shelters.';
            } finally {
                btn.disabled = false;
                btn.innerHTML = originalBtnHtml;
                if (window.lucide) lucide.createIcons();
            }
        },
        (error) => {
            console.warn('Geolocation error:', error);
            btn.disabled = false;
            btn.innerHTML = originalBtnHtml;
            alert('Location access is required to find nearby shelters within 10 km. Please enable GPS/location permissions in your browser.');
            if (statusText) statusText.innerText = 'Location access is required to find nearby shelters within 10 km.';
            if (window.lucide) lucide.createIcons();
        },
        { enableHighAccuracy: true, timeout: 10000 }
    );
}

function resetSheltersList() {
    window.location.reload();
}

function escapeHtml(str) {
    if (!str) return '';
    return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

async function findBestShelter() {
    const modal = new bootstrap.Modal(document.getElementById('bestShelterModal'));
    modal.show();

    const lat = sessionStorage.getItem('rudram_lat') || '20.2961';
    const lon = sessionStorage.getItem('rudram_lon') || '85.8245';

    try {
        const res = await fetch(`/api/shelters/recommend/?lat=${lat}&lon=${lon}&medical_required=true`);
        const data = await res.json();
        if (data.success && data.best_match) {
            const b = data.best_match;
            document.getElementById('bestShelterModalBody').innerHTML = `
                <div class="p-3 bg-primary bg-opacity-10 border border-primary border-opacity-50 rounded mb-3">
                    <span class="badge bg-success mb-1">SUITABILITY SCORE: ${b.suitability_score}%</span>
                    <h5 class="fw-bold text-white mb-1">${escapeHtml(b.name)}</h5>
                    <div class="small text-secondary mb-2">${escapeHtml(b.address)}</div>
                    <div class="row g-2 small mb-2">
                        <div class="col-6"><strong>Distance:</strong> <span class="text-info">${b.distance_km} km</span></div>
                        <div class="col-6"><strong>Free Capacity:</strong> <span class="text-success">${b.available_capacity} beds</span></div>
                        <div class="col-6"><strong>Elevation:</strong> <span class="text-warning">${b.elevation_m}m</span></div>
                        <div class="col-6"><strong>Medical Station:</strong> <span class="text-danger">${b.has_medical_station ? 'YES' : 'NO'}</span></div>
                    </div>
                </div>
                <div class="small text-muted">
                    <strong>Algorithmic Rationale:</strong> Ranked highest due to elevated high-ground terrain (clear of Kuakhai flood surge), immediate available bed capacity, and on-site medical trauma unit.
                </div>
            `;
            const modalNavBtn = document.querySelector('#bestShelterModal .modal-footer a');
            if (modalNavBtn) {
                modalNavBtn.href = `/evacuation/?shelter_id=${b.id}`;
            }
            lucide.createIcons();
        }
    } catch (e) {
        document.getElementById('bestShelterModalBody').innerHTML = '<div class="alert alert-danger">Error retrieving shelter recommendation.</div>';
    }
}

async function quickUpdateOccupancy(id, current) {
    const newOcc = prompt("Enter updated headcount for shelter:", current + 50);
    if (newOcc !== null) {
        try {
            const res = await fetch(`/api/shelters/${id}/update-occupancy/`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ current_occupancy: parseInt(newOcc) })
            });
            const data = await res.json();
            if (data.success) {
                showToast('Shelter occupancy updated successfully!', 'success');
                setTimeout(() => window.location.reload(), 800);
            }
        } catch (e) {
            showToast('Error updating occupancy', 'error');
        }
    }
}
</script>
{% endblock %}

