    <div class="alert alert-info small">For urgent help in India, call 112. Follow official local evacuation orders.</div>
    <div id="chatMessageStream" class="d-flex flex-column gap-3 my-4" aria-live="polite"></div>
    <form id="copilotForm" class="d-flex gap-2">
        <label for="userInput" class="visually-hidden">Your question</label>
        <input id="userInput" class="form-control" placeholder="How do I prepare for a cyclone?" maxlength="2000" required>
        <button class="btn btn-primary" type="submit">Send</button>
    </form>
</div>
