{% block extra_js %}
<script>
const chatForm = document.getElementById('copilotForm');
chatForm.addEventListener('submit', async event => {
    event.preventDefault();
    const input = document.getElementById('userInput');
    const message = input.value.trim();
    if (!message) return;
    const stream = document.getElementById('chatMessageStream');
    const question = document.createElement('div'); question.className = 'text-info'; question.textContent = message; stream.append(question);
    const reply = document.createElement('div'); reply.className = 'p-3 border rounded'; reply.style.whiteSpace = 'pre-wrap'; reply.textContent = 'Reading preparedness guidance…'; stream.append(reply);
    chatForm.querySelector('button').disabled = true; input.value = '';
    try {
        const response = await fetch('/api/assistant/chat/', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ message }) });
        const data = await response.json();
        reply.textContent = data.reply || data.message || 'Guidance is temporarily unavailable.';
    } catch { reply.textContent = 'Unable to connect. Please try again.'; }
    finally { chatForm.querySelector('button').disabled = false; input.focus(); }
});
</script>
{% endblock %}

