{% extends 'base.html' %}

{% block title %}RUDRAM - AI Flood Risk Prediction Engine{% endblock %}
{% block meta_description %}Assess location-based flood risk using rainfall, terrain, river levels, and predictive analytics in RUDRAM.{% endblock %}
{% block page_heading %}AI Flood Risk Prediction & SHAP Factor Breakdown{% endblock %}

{% block content %}
<div class="alert alert-info small">Experimental flood estimates use trained repository models and live weather. Missing hydrological observations use disclosed assumptions. These estimates are not official warnings.</div>
<div class="row g-4">
    <!-- Input Parameter Studio Form -->
    <div class="col-lg-5">
        <div class="rudram-card">
            <div class="d-flex align-items-center justify-content-between mb-3 border-bottom border-secondary border-opacity-25 pb-2">
