                            <button class="btn btn-info font-monospace text-dark fw-bold d-flex align-items-center gap-1" type="button" id="btnUseCurrentLoc" onclick="useCurrentLocation()">
                                <i data-lucide="map-pin" style="width: 14px; height: 14px;"></i> Use Current Location
                            </button>
                        </div>
                        <div id="riskLocSearchResults" class="dropdown-menu dropdown-menu-dark w-100 shadow-lg mt-1" style="display: none; max-height: 250px; overflow-y: auto; z-index: 1050;"></div>
                    </div>
                    <div class="col-6">
                        <label class="form-label small text-secondary">Latitude</label>
                        <input type="number" step="0.0001" id="lat" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Lat (-90 to 90)">
                    </div>
                    <div class="col-6">
                        <label class="form-label small text-secondary">Longitude</label>
                        <input type="number" step="0.0001" id="lon" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Lon (-180 to 180)">
                    </div>
                </div>

                <div class="row g-2 mb-3">
                    <div class="col-6">
                        <label class="form-label small text-secondary">Current Rain Rate (mm/hr)</label>
                        <input type="number" id="rainCurr" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Auto-filled live" step="0.1">
                    </div>
                    <div class="col-6">
                        <label class="form-label small text-secondary">24-Hour Rainfall (mm)</label>
                        <input type="number" id="rain24h" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Auto-filled live" step="0.1">
                    </div>
                    <div class="col-6">
                        <label class="form-label small text-secondary">7-Day Antecedent Rain (mm)</label>
                        <input type="number" id="rain7d" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Auto-filled live" step="0.1">
                    </div>
                    <div class="col-6">
                        <label class="form-label small text-secondary">24h Forecast Rain (mm)</label>
                        <input type="number" id="rainFc" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Auto-filled live" step="0.1">
                    </div>
                    <div class="col-4">
                        <label class="form-label small text-secondary">Temperature (°C)</label>
                        <input type="number" id="tempC" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Auto-filled live" step="0.1">
                    </div>
                    <div class="col-4">
                        <label class="form-label small text-secondary">Humidity (%)</label>
                        <input type="number" id="humidityPct" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Auto-filled live" step="0.1">
                    </div>
                    <div class="col-4">
                        <label class="form-label small text-secondary">Wind Speed (km/h)</label>
                        <input type="number" id="windKmh" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Auto-filled live" step="0.1">
                    </div>
                    <div class="col-6">
                        <label class="form-label small text-secondary">Elevation (m a.s.l.)</label>
                        <input type="number" id="elev" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Leave blank if unmeasured" step="1">
                    </div>
                    <div class="col-6">
                        <label class="form-label small text-secondary">Distance to River (km)</label>
                        <input type="number" step="0.1" id="distWater" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Leave blank if unmeasured">
                    </div>
                    <div class="col-6">
                        <label class="form-label small text-secondary">River Gauge Level (m)</label>
                        <input type="number" step="0.1" id="riverLevel" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Leave blank if unmeasured">
                    </div>
                    <div class="col-6">
                        <label class="form-label small text-secondary">Soil Saturation Index (0-1)</label>
                        <input type="number" step="0.01" id="soilMoist" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Leave blank if unmeasured">
