                            <td class="text-white fw-semibold">{{ req.target_object_name|default:req.target_model }}</td>
                            <td><code class="text-info">{{ req.requested_changes }}</code></td>
                            <td class="text-secondary small">{{ req.reason }}</td>
                            <td>
                                {% if req.status == 'PENDING' %}
                                    <span class="badge bg-warning text-dark fw-bold">PENDING APPROVAL</span>
                                {% elif req.status == 'APPROVED' %}
