{% block extra_js %}
<script>
let allocModal = null;

// Utility to retrieve CSRF token for API fetch requests
function getCsrfToken() {
    let cookieValue = null;
    if (document.cookie && document.cookie !== '') {
        const cookies = document.cookie.split(';');
        for (let i = 0; i < cookies.length; i++) {
            const cookie = cookies[i].trim();
            if (cookie.substring(0, 10) === 'csrftoken=') {
                cookieValue = decodeURIComponent(cookie.substring(10));
                break;
            }
        }
    }
    if (cookieValue) return cookieValue;
    const csrfInput = document.querySelector('[name=csrfmiddlewaretoken]');
    return csrfInput ? csrfInput.value : '';
}

// Global modal cleanup & focus release
function cleanupStaleModalBackdrops() {
    const openModals = document.querySelectorAll('.modal.show');
    if (openModals.length === 0) {
        document.querySelectorAll('.modal-backdrop').forEach(el => el.remove());
        document.body.classList.remove('modal-open');
        document.body.style.removeProperty('overflow');
        document.body.style.removeProperty('padding-right');
    }
}

document.addEventListener('hide.bs.modal', function (e) {
    if (e.target && e.target.contains(document.activeElement)) {
        document.activeElement.blur();
    }
});

document.addEventListener('hidden.bs.modal', function (e) {
    if (e.target && e.target.contains(document.activeElement)) {
        document.activeElement.blur();
    }
    cleanupStaleModalBackdrops();
});

document.addEventListener('DOMContentLoaded', () => {
    cleanupStaleModalBackdrops();
    const allocEl = document.getElementById('allocateModal');
    if (allocEl) allocModal = new bootstrap.Modal(allocEl);
});

function openAllocateModal() {
    if (allocModal) allocModal.show();
}

function quickAllocateItem(id, name, avail) {
    const sel = document.getElementById('allocResourceSelect');
    if (sel) sel.value = id;
    const qtyInput = document.getElementById('allocQty');
    if (qtyInput) qtyInput.value = Math.min(500, avail);
    openAllocateModal();
}

const allocForm = document.getElementById('allocateForm');
if (allocForm) {
    allocForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        const resId = document.getElementById('allocResourceSelect').value;
        const qty = parseInt(document.getElementById('allocQty').value);
        const dest = document.getElementById('allocDest').value;
        const notes = document.getElementById('allocNotes').value;

        if (document.activeElement) document.activeElement.blur();

        try {
            const res = await fetch('/api/resources/allocate/', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRFToken': getCsrfToken()
                },
                body: JSON.stringify({
                    resource_id: resId,
                    quantity: qty,
                    destination_zone: dest,
                    notes: notes
                })
            });
            const data = await res.json();
            if (res.status === 403) {
                showToast(data.error || 'Access Denied: You do not have permission to perform this operational action.', 'error');
                if (allocModal) allocModal.hide();
                return;
            }
            if (data.pending) {
                showToast('Dispatch request submitted for Admin approval. Stock will remain unchanged until approved.', 'info');
                if (allocModal) allocModal.hide();
                setTimeout(() => window.location.reload(), 1000);
            } else if (data.success) {
                showToast(`Authorized dispatch of ${qty} units to ${dest}!`, 'success');
                if (allocModal) allocModal.hide();
                setTimeout(() => window.location.reload(), 800);
            } else {
                showToast(data.error || 'Allocation error', 'error');
            }
        } catch (err) {
            showToast('Network error during resource allocation', 'error');
        }
    });
}
</script>
{% endblock %}

evacuation/index.html:
{% extends 'base.html' %}

{% block title %}RUDRAM - Safe Evacuation & Dynamic Route Planner{% endblock %}
{% block meta_description %}Plan safer evacuation routes and find emergency shelters using RUDRAM location and hazard intelligence.{% endblock %}
{% block page_heading %}Safe Evacuation & Hazard-Aware Routing Engine{% endblock %}

{% block content %}
<div class="alert alert-warning small">Road routes do not verify flooding, closures, or evacuation safety. Follow current local evacuation orders.</div>
{% csrf_token %}
<div class="row g-4">
    <!-- Routing Input Panel -->
    <div class="col-lg-4">
        <div class="rudram-card mb-4">
            <h6 class="fw-bold mb-3 d-flex align-items-center gap-2">
                <i data-lucide="navigation" class="text-info" style="width: 18px; height: 18px;"></i>
                Evacuation Origin & Safe Haven
            </h6>

            <form id="evacuationRouteForm">
                <div class="mb-3">
                    <label class="form-label small text-secondary">Origin / Current GPS Position</label>
                    <div class="input-group input-group-sm mb-1">
                        <input type="text" id="startName" class="form-control bg-dark border-secondary text-light" placeholder="Locating position..." readonly required>
                        <button type="button" class="btn btn-outline-info" onclick="useMyGps()" title="Request Real GPS Location">
                            <i data-lucide="crosshair" style="width: 14px; height: 14px;"></i>
                        </button>
                    </div>
                    <div class="row g-1 small text-secondary">
                        <div class="col-6"><input type="number" step="any" id="startLat" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Latitude" readonly required></div>
                        <div class="col-6"><input type="number" step="any" id="startLon" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Longitude" readonly required></div>
                    </div>
                </div>

                <div class="mb-3">
                    <label class="form-label small text-secondary d-flex justify-content-between">
