                    </label>
                    <select id="destSelect" class="form-select form-select-sm bg-dark border-secondary text-light mb-1" onchange="updateDestCoords()" required>
                        <option value="">Loading Admin shelters...</option>
                    </select>
                    <div class="row g-1 small text-secondary">
                        <div class="col-6"><input type="number" step="any" id="destLat" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Shelter Lat" readonly required></div>
                        <div class="col-6"><input type="number" step="any" id="destLon" class="form-control form-control-sm bg-dark border-secondary text-light" placeholder="Shelter Lon" readonly required></div>
                    </div>
                </div>

                <button type="submit" class="btn btn-primary w-100 fw-bold d-flex align-items-center justify-content-center gap-2" id="btnCalculateRoute">
                    <i data-lucide="search" style="width: 16px; height: 16px;"></i>
                    SEARCH SAFE PATH
                </button>
