        </div>

        <!-- Live Route & Safety Breakdown Container -->
        <div id="routeResultsContainer">
            <h6 class="fw-bold mb-2 small text-uppercase text-secondary">Live Route Breakdown</h6>
            <div id="routeStatusCard" class="rudram-card p-3 border-secondary text-secondary small">
                Select current GPS position and target Admin Safe Shelter, then click <strong>Search Safe Path</strong>.
            </div>
        </div>
    </div>

    <!-- Evacuation Route Map -->
    <div class="col-lg-8">
        <div class="rudram-card p-0 overflow-hidden" style="height: 620px;">
