<!-- Admin Global Demo Data Control Card (ADMIN ONLY) -->
<div class="row g-4 mb-4">
    <div class="col-12">
        <div class="rudram-card border-warning border-opacity-50">
            <div class="d-flex align-items-center justify-content-between flex-wrap gap-3">
