                        GLOBAL DEMO DATA MODE CONTROL
                    </h6>
                    <div class="small text-secondary">Controls whether the platform operates on <strong>LIVE DATA ONLY</strong> or engages <strong>SIMULATION / DEMO DATA</strong>. Default is <strong>OFF (Live Data Only)</strong>. Admin privilege required to toggle.</div>
                </div>
                <div class="d-flex align-items-center gap-3">
                    <span class="badge {% if DEMO_MODE %}bg-warning text-dark{% else %}bg-success text-white{% endif %} fs-6 px-3 py-2 fw-bold" id="demoModeBadge">
                        {% if DEMO_MODE %}DEMO MODE (ON){% else %}LIVE DATA (OFF){% endif %}
                    </span>
                    <div class="btn-group" role="group" aria-label="Demo Mode Toggle">
                        <input type="radio" class="btn-check" name="demoModeRadio" id="demoModeOff" value="false" autocomplete="off" {% if not DEMO_MODE %}checked{% endif %} onchange="toggleAdminDemoMode(false)">
                        <label class="btn btn-outline-success px-3 fw-bold" for="demoModeOff"><i data-lucide="check-circle" class="me-1" style="width: 15px; height: 15px;"></i>OFF (Live Data)</label>

                        <input type="radio" class="btn-check" name="demoModeRadio" id="demoModeOn" value="true" autocomplete="off" {% if DEMO_MODE %}checked{% endif %} onchange="toggleAdminDemoMode(true)">
                        <label class="btn btn-outline-warning px-3 fw-bold" for="demoModeOn"><i data-lucide="play-circle" class="me-1" style="width: 15px; height: 15px;"></i>ON (Demo Mode)</label>
                    </div>
                </div>
            </div>
            <div id="demoModeStatusAlert" class="alert alert-dark py-2 px-3 small mt-3 mb-0 border-secondary" style="display: none;"></div>
        </div>
    </div>
</div>

<script>
async function toggleAdminDemoMode(enableDemo) {
    const alertBox = document.getElementById('demoModeStatusAlert');
    const badgeBox = document.getElementById('demoModeBadge');
    const csrfToken = document.querySelector('[name=csrfmiddlewaretoken]')?.value || '';

    try {
        const res = await fetch('/api/admin/demo-mode/', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRFToken': csrfToken
            },
            body: JSON.stringify({ demo_mode: enableDemo })
        });

        if (!res.ok) {
            if (alertBox) {
                alertBox.style.display = 'block';
                alertBox.className = 'alert alert-danger py-2 px-3 small mt-3 mb-0';
                alertBox.innerText = `Access Denied (HTTP ${res.status}). Only system administrators can change Demo Mode.`;
            }
            return;
        }

        const data = await res.json();
        if (data.success) {
            const isDemo = data.demo_mode;
            if (badgeBox) {
                badgeBox.innerText = isDemo ? 'DEMO MODE (ON)' : 'LIVE DATA (OFF)';
                badgeBox.className = isDemo ? 'badge bg-warning text-dark fs-6 px-3 py-2 fw-bold' : 'badge bg-success text-white fs-6 px-3 py-2 fw-bold';
            }

            if (alertBox) {
                alertBox.style.display = 'block';
                alertBox.className = isDemo ? 'alert alert-warning py-2 px-3 small mt-3 mb-0' : 'alert alert-success py-2 px-3 small mt-3 mb-0';
                alertBox.innerText = isDemo ? '⚠️ Demo Data Mode is now ENABLED globally. Platform features will use simulation datasets.' : '✅ Live Data Mode is now ENABLED globally (OFF). Platform features will use live APIs only.';
            }

            if (typeof showToast === 'function') {
                showToast(isDemo ? 'Demo Data Mode Enabled' : 'Live Data Mode Enabled (OFF)', isDemo ? 'warning' : 'success');
            }
        }
    } catch (e) {
        console.error('Demo Mode toggle error:', e);
        if (alertBox) {
            alertBox.style.display = 'block';
            alertBox.className = 'alert alert-danger py-2 px-3 small mt-3 mb-0';
            alertBox.innerText = 'Network error while updating global Demo Mode.';
        }
    }
}
</script>

<!-- Admin API Health Monitoring Panel (ADMIN ONLY) -->
<div class="row g-4 mb-4">
    <div class="col-12">
        <div class="rudram-card border-info border-opacity-50">
            <div class="d-flex align-items-center justify-content-between mb-3">
