                        Admin API Health &amp; Services Telemetry
                    </h6>
                    <div class="small text-secondary">Real-time health diagnostics across Google Maps Platform, Weather Telemetry, Remote Sensing, &amp; ML Models. (Admin Only)</div>
                </div>
                <button class="btn btn-sm btn-info fw-bold text-dark px-3" id="btnRunApiHealthCheck" onclick="runAdminApiHealthDiagnostics()">
                    <i data-lucide="play" class="me-1" style="width: 14px; height: 14px;"></i>Check APIs
                </button>
            </div>

            <div id="apiHealthStatusAlert" class="alert alert-dark py-2 px-3 small mb-3 border-secondary" style="display: none;"></div>

            <div class="table-responsive">
                <table class="table table-dark table-hover small mb-0" style="font-size: 0.8rem;">
                    <thead>
                        <tr class="text-secondary">
                            <th>API / SERVICE NAME</th>
                            <th>CATEGORY</th>
                            <th>HEALTH STATUS</th>
                            <th>RESPONSE LATENCY</th>
                            <th>DETAILS / TELEMETRY</th>
                        </tr>
                    </thead>
                    <tbody id="apiHealthTableBody">
                        <tr><td colspan="5" class="text-muted text-center py-3">Click "Check APIs" above to run real-time diagnostic health check.</td></tr>
                    </tbody>
                </table>
            </div>
        </div>
    </div>
</div>

<script>
async function runAdminApiHealthDiagnostics() {
    const btn = document.getElementById('btnRunApiHealthCheck');
    const tbody = document.getElementById('apiHealthTableBody');
    const alertBox = document.getElementById('apiHealthStatusAlert');

    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Running Health Check...';
    }

    try {
        const res = await fetch('/api/admin/api-health/');
        if (!res.ok) {
            if (alertBox) {
                alertBox.style.display = 'block';
                alertBox.className = 'alert alert-danger py-2 px-3 small mb-3';
                alertBox.innerText = `Health Check Access Denied (HTTP ${res.status}). Admin privileges required.`;
            }
            return;
        }

        const data = await res.json();
        if (data.success && Array.isArray(data.services)) {
            let html = '';
            data.services.forEach(s => {
                let badgeClass = 'bg-success text-white';
                if (s.status === 'DEGRADED') badgeClass = 'bg-warning text-dark';
                else if (s.status === 'FAILED' || s.status === 'TIMEOUT') badgeClass = 'bg-danger text-white';
                else if (s.status === 'NOT_CONFIGURED') badgeClass = 'bg-secondary text-white';

                html += `
                    <tr>
                        <td><strong class="text-white">${s.service}</strong></td>
                        <td><span class="badge bg-dark border border-secondary text-info">${s.category}</span></td>
                        <td><span class="badge ${badgeClass} fw-bold">${s.status}</span></td>
                        <td class="font-monospace text-info">${s.response_time_ms > 0 ? s.response_time_ms + ' ms' : '--'}</td>
                        <td class="text-secondary">${s.details || 'Operational'}</td>
                    </tr>
                `;
            });
            tbody.innerHTML = html;

            if (alertBox) {
                alertBox.style.display = 'block';
                alertBox.className = 'alert alert-success py-2 px-3 small mb-3';
                alertBox.innerText = `✅ Diagnostic Health Check Completed — ${data.healthy_services}/${data.total_services} Services Healthy.`;
            }
        }
    } catch (e) {
        console.error('API Health check error:', e);
        if (alertBox) {
            alertBox.style.display = 'block';
            alertBox.className = 'alert alert-danger py-2 px-3 small mb-3';
            alertBox.innerText = 'Network error while executing API Health Diagnostic Check.';
        }
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = '<i data-lucide="play" class="me-1" style="width: 14px; height: 14px;"></i>Check APIs';
            if (window.lucide) lucide.createIcons();
        }
    }
}
</script>
{% endif %}

