{% extends 'base.html' %}

{% block title %}RUDRAM - Citizen Registration{% endblock %}
{% block meta_description %}Create a RUDRAM citizen account to access local emergency alerts, shelter information, and disaster response resources.{% endblock %}
{% block page_heading %}Citizen Public Account Registration{% endblock %}

{% block content %}
<div class="row justify-content-center py-4">
    <div class="col-md-6 col-lg-5">
        <div class="rudram-card border border-info border-opacity-50 position-relative">
            <!-- Black Close Create Account Button (×) -->
            <button type="button" class="btn p-0 text-dark fw-bold position-absolute top-0 end-0 m-3 border-0 bg-transparent" onclick="closeSignupPage()" aria-label="Close create account" title="Close create account" style="font-size: 1.6rem; line-height: 1; opacity: 0.85; z-index: 10; cursor: pointer;">&times;</button>
            <div class="text-center mb-4">
                <div class="bg-info bg-opacity-25 text-info p-3 rounded-circle d-inline-flex align-items-center justify-content-center mb-2" style="width: 54px; height: 54px;">
                    <i data-lucide="user-plus" style="width: 28px; height: 28px;"></i>
                </div>
                <h4 class="fw-bold text-white mb-1">Create Citizen Account</h4>
                <div class="small text-secondary">Public Emergency Safety &amp; Risk Notification Node</div>
            </div>

            {% if messages %}
                {% for message in messages %}
                    <div class="alert alert-{% if message.tags == 'error' %}danger{% else %}{{ message.tags }}{% endif %} alert-dismissible fade show small py-2 px-3 mb-3" role="alert">
                        {{ message }}
                        <button type="button" class="btn-close py-2" data-bs-dismiss="alert" aria-label="Close"></button>
                    </div>
                {% endfor %}
            {% endif %}

            <form method="POST" action="{% url 'citizen_signup' %}">
                {% csrf_token %}
                <div class="mb-3">
                    <label class="form-label small text-secondary">Full Name <span class="text-danger">*</span></label>
                    <input type="text" name="full_name" class="form-control bg-dark border-secondary text-light" placeholder="e.g. Ramesh Chandra Das" value="{{ form_data.full_name|default:'' }}" required autofocus>
                </div>

                <div class="mb-3">
                    <label class="form-label small text-secondary">Email Address <span class="text-danger">*</span></label>
                    <input type="email" name="email" class="form-control bg-dark border-secondary text-light" placeholder="name@example.com" value="{{ form_data.email|default:'' }}" required>
                </div>

                <div class="mb-3">
                    <label class="form-label small text-secondary">Phone Number <span class="text-danger">*</span></label>
                    <input type="tel" name="phone_number" class="form-control bg-dark border-secondary text-light" placeholder="+91 9876543210" value="{{ form_data.phone_number|default:'' }}" required>
                </div>

                <div class="row g-2 mb-4">
                    <div class="col-6">
                        <label class="form-label small text-secondary">Password <span class="text-danger">*</span></label>
                        <div class="input-group">
                            <input type="password" name="password" id="signupPasswordInput" class="form-control form-control-sm bg-dark border-secondary text-light border-end-0" placeholder="••••••••" required>
                            <button type="button" class="btn btn-sm btn-dark border-secondary border-start-0 text-secondary" id="btnToggleSignupPass" onclick="toggleSignupPassVisibility()" aria-label="Show password" title="Show password">
                                <i data-lucide="eye" id="toggleSignupPassIcon" style="width: 16px; height: 16px;"></i>
                            </button>
                        </div>
                    </div>
                    <div class="col-6">
                        <label class="form-label small text-secondary">Confirm Password <span class="text-danger">*</span></label>
                        <div class="input-group">
                            <input type="password" name="confirm_password" id="signupConfirmInput" class="form-control form-control-sm bg-dark border-secondary text-light border-end-0" placeholder="••••••••" required>
                            <button type="button" class="btn btn-sm btn-dark border-secondary border-start-0 text-secondary" id="btnToggleSignupConfirm" onclick="toggleSignupConfirmVisibility()" aria-label="Show password" title="Show password">
                                <i data-lucide="eye" id="toggleSignupConfirmIcon" style="width: 16px; height: 16px;"></i>
                            </button>
                        </div>
                    </div>
                </div>

                <button type="submit" class="btn btn-info w-100 fw-bold py-2 text-dark">
                    CREATE CITIZEN ACCOUNT
                </button>
            </form>

            <div class="mt-4 pt-3 border-top border-secondary border-opacity-25 small text-secondary text-center">
                Already registered?
                <a href="{% url 'login' %}" class="text-info fw-bold text-decoration-none ms-1">Log in here</a>
            </div>
        </div>
    </div>
</div>
{% endblock %}

